const IMGDATA = {"thread-overview": "data:image/png;base64,", "im500-context": "data:image/png;base64,", "ai-concept-quadrant": "data:image/png;base64,", "agent-anatomy": "data:image/png;base64,", "orchestration-abc": "data:image/png;base64,", "orchestration-patterns": "data:image/png;base64,", "end-to-end-pipeline": "data:image/png;base64,", "rag-pipeline": "data:image/png;base64,", "rag-beforeafter": "data:image/png;base64,"};

const pptxgen = require("pptxgenjs");
const p = new pptxgen();
p.defineLayout({ name: "W", width: 13.333, height: 7.5 });
p.layout = "W";
p.author = "Arjun Thakur"; p.company = "arjunthakur.dev";
const BG="0B0F15", BG_DEEP="06090D", CARD="11161E", BORDER="1F2937";
const CYAN="22D3EE", TEAL="0E7490", WHITE="E6EDF3", SECOND="AAB4C0", MUTED="8592A3";
const AMBER="F59E0B", GREEN="34D399", PURPLE="A78BFA";
const SANS="Calibri", MONO="Consolas";
const DARK={color:BG}, DEEP={color:BG_DEEP};
const WEB="arjunthakur.dev";
function footer(s){ s.addText(WEB,{x:0.9,y:7.05,w:6,h:0.3,fontFace:SANS,fontSize:11,color:SECOND,charSpacing:1}); }
function newSlide(bg){ const s=p.addSlide(); s.background=bg; footer(s); return s; }
function kicker(s,txt,x=0.9,y=0.7){ s.addText(txt,{x,y,w:11.5,h:0.4,fontFace:SANS,fontSize:14,bold:true,color:CYAN,charSpacing:4}); }
function bullets(items,gap=16){ const arr=[]; items.forEach((it)=>{ arr.push({text:"▸  ",options:{color:CYAN,bold:true,fontFace:SANS}}); arr.push({text:it,options:{color:WHITE,fontFace:SANS,breakLine:true,paraSpaceAfter:gap}}); }); return arr; }
function content(kickerTxt,title,items,bg=DARK,fontSize=20,gap=16){
  const s=newSlide(bg); kicker(s,kickerTxt,0.9,0.72);
  s.addText(title,{x:0.9,y:1.18,w:11.6,h:0.9,fontFace:SANS,fontSize:32,bold:true,color:WHITE});
  s.addText(bullets(items,gap),{x:0.9,y:2.35,w:11.5,h:4.0,fontFace:SANS,fontSize:fontSize,color:WHITE,valign:"top",objectName:"animList"});
  return s;
}
function url(s,txt,y){ s.addText([{text:"↗  ",options:{color:AMBER,bold:true}},{text:txt,options:{color:CYAN}}],{x:0.9,y:y||6.62,w:11.5,h:0.32,fontFace:SANS,fontSize:14}); }
function askRoom(s,q,y){ s.addText([{text:"Ask the room:  ",options:{color:AMBER,bold:true}},{text:q,options:{color:WHITE,italic:true}}],{x:0.9,y:y||6.5,w:11.5,h:0.5,fontFace:SANS,fontSize:16}); }
function divider(numStr,kickerTxt,title,subtitle){
  const s=newSlide(DEEP);
  s.addText(numStr,{x:0.82,y:0.5,w:6,h:2.6,fontFace:SANS,fontSize:150,bold:true,color:TEAL});
  kicker(s,kickerTxt,0.95,3.5);
  s.addText(title,{x:0.9,y:3.9,w:11.6,h:1.1,fontFace:SANS,fontSize:44,bold:true,color:WHITE});
  if(subtitle) s.addText(subtitle,{x:0.94,y:5.05,w:11.2,h:0.6,fontFace:SANS,fontSize:17,italic:true,color:MUTED});
  return s;
}
function breakSlide(mins,mark){
  const s=newSlide(DEEP);
  s.addText("BREAK",{x:0.9,y:2.15,w:11.5,h:1.0,align:"center",fontFace:SANS,fontSize:60,bold:true,color:CYAN,charSpacing:8});
  s.addText(mins+" minutes",{x:0.9,y:3.45,w:11.5,h:0.8,align:"center",fontFace:SANS,fontSize:28,color:WHITE});
  s.addText("We'll resume right on time.",{x:0.9,y:4.35,w:11.5,h:0.6,align:"center",fontFace:SANS,fontSize:17,italic:true,color:MUTED});
  s.addNotes(mark||""); return s;
}
function qaSlide(title,prompts){
  const s=newSlide(DEEP); kicker(s,"Q & A",0.9,1.1);
  s.addText(title,{x:0.9,y:1.5,w:11.5,h:1.2,fontFace:SANS,fontSize:50,bold:true,color:WHITE});
  if(prompts&&prompts.length) s.addText(bullets(prompts,16),{x:0.9,y:3.05,w:11.5,h:2.2,fontFace:SANS,fontSize:20,color:WHITE,valign:"top"});
  return s;
}
function chip(s,x,y,w,h,title,sub,accent=CYAN){
  s.addShape(p.ShapeType.roundRect,{x,y,w,h,rectRadius:0.08,fill:{color:CARD},line:{color:accent,width:1.5}});
  s.addText(title,{x:x+0.08,y:sub?y+0.1:y,w:w-0.16,h:sub?h-0.55:h,align:"center",valign:"middle",fontFace:SANS,fontSize:15,bold:true,color:WHITE});
  if(sub) s.addText(sub,{x:x+0.08,y:y+h-0.52,w:w-0.16,h:0.44,align:"center",valign:"middle",fontFace:SANS,fontSize:11,color:SECOND});
}
function arrow(s,x,y,w,accent=CYAN){ s.addShape(p.ShapeType.line,{x,y,w,h:0,line:{color:accent,width:2.75,endArrowType:"triangle"}}); }
function flowRow(s,items,y,chipH=1.15,accent=CYAN){
  const n=items.length,totalW=11.5,x0=0.9,gap=0.55; const chipW=(totalW-gap*(n-1))/n;
  items.forEach((it,i)=>{ const x=x0+i*(chipW+gap); chip(s,x,y,chipW,chipH,it.t,it.s,it.a||accent); if(i<n-1) arrow(s,x+chipW+0.07,y+chipH/2,gap-0.14,accent); });
}
function figure(kickerTxt,title,key,note,caption){
  const s=newSlide(DARK); kicker(s,kickerTxt,0.9,0.62);
  s.addText(title,{x:0.9,y:1.02,w:11.6,h:0.7,fontFace:SANS,fontSize:30,bold:true,color:WHITE});
  const bx=0.9,by=1.92,bw=11.53,bh=caption?4.35:4.7;
  s.addShape(p.ShapeType.roundRect,{x:bx,y:by,w:bw,h:bh,rectRadius:0.08,fill:{color:BG},line:{color:BORDER,width:1.25}});
  s.addImage({data:IMGDATA[key],x:bx+0.15,y:by+0.15,w:bw-0.3,h:bh-0.3,sizing:{type:"contain",w:bw-0.3,h:bh-0.3}});
  if(caption) s.addText(caption,{x:0.9,y:by+bh+0.12,w:11.5,h:0.4,fontFace:SANS,fontSize:15,italic:true,color:CYAN,align:"center"});
  if(note) s.addNotes(note); return s;
}
function demoSlide(kickerTxt,title,tool,steps,note,urlTxt){
  const s=newSlide(DEEP);
  s.addText("▶  LIVE DEMO",{x:0.9,y:0.72,w:11.5,h:0.5,fontFace:SANS,fontSize:18,bold:true,color:AMBER,charSpacing:3});
  s.addText(title,{x:0.9,y:1.28,w:11.6,h:0.9,fontFace:SANS,fontSize:34,bold:true,color:WHITE});
  s.addText([{text:"Leave the deck → ",options:{color:SECOND}},{text:tool,options:{color:CYAN,bold:true}}],{x:0.92,y:2.25,w:11.5,h:0.5,fontFace:SANS,fontSize:18,italic:true});
  s.addText(bullets(steps,14),{x:0.9,y:3.0,w:11.5,h:3.1,fontFace:SANS,fontSize:19,color:WHITE,valign:"top"});
  if(urlTxt) url(s,urlTxt,6.5);
  if(note) s.addNotes(note); return s;
}

/* OPENING */
