s.addText("A hands-on, 4-hour session - concepts, RAG, agents and orchestration, all no-code",{x:0.94,y:3.2,w:11.4,h:0.6,fontFace:SANS,fontSize:18,italic:true,color:MUTED});
s.addText([{text:"Presented by ",options:{color:SECOND}},{text:"Arjun Thakur",options:{color:WHITE,bold:true}}],{x:0.92,y:4.4,w:11.5,h:0.5,fontFace:SANS,fontSize:24});
s.addText("Principal AI Engineer  ·  AI Trainer  ·  Agentic AI Developer",{x:0.94,y:5.0,w:11.5,h:0.4,fontFace:SANS,fontSize:15,color:SECOND});
